// @ts-nocheck
/* eslint-disable */
/**
 * Receipt list engine. GENERATED by tools/sync-receipts.mjs from web/pages/sales_doc_rv_list.xhtml + web/resources/support/sd2_list.css — do not edit; change the script and run `npm run receipts:sync`.
 *
 * The page script of the Java screen, same behaviour line by line: the table of receipts (loaded once, 500 rows; search, status filter,
 * product filter and sorting happen on the client), the customer suggestions under the search field, the approve dialog and its POST, the
 * report popover (the ERP form RV-01 as PDF / PNG, or the preview made from the CRM data) and the detail modal.
 *
 * WHY it is imperative DOM code and not Angular components: the Java page draws its HTML from API data as strings. Porting it 1:1 is what
 * guarantees the screen, texts and states are identical to the production system.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java file (all of it lives in tools/sync-receipts.mjs):
 *   - the environment is injected (ReceiptsEnv): messages, permissions, fetch (the BFF contract of receipts-backend.ts), window.open,
 *     navigation to the form, SweetAlert, the stored product filter (TS_PREF), the context path — in Java these were EL, the URL and globals;
 *   - the strip of tabs that sales_doc_tabs.xhtml injects into the Java top bar is drawn by the Angular shell (nav.config.ts);
 *   - the addresses '../rvapi…' are '/rvapi…' (below the context path); the link to the form is its route;
 *   - global listeners and timers added through listen() / tmo(), the two overlays the script moves to <body>, and the response guard are
 *     removed by the function returned from startReceipts().
 */

export interface ReceiptsEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** commonBean.hasFeature('A,B') of the signed-in user (OR of the keys) */
  can: (features: string) => boolean;
  /** the BFF contract of the page: /rvapi?action=…, /board/prospect-list (see receipts-backend.ts) */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** window.open(url, target) — a report address (/rvreport…, /rvreceipt…) or the blob URL of the receipt image */
  open: (url: string, target?: string) => unknown;
  /** window.location.href = … : the route of this app */
  navigate: (route: string) => void;
  /** SweetAlert v2 (js/sweetalert/sweetalertv1.min.js) */
  swal: (options: Record<string, unknown>) => Promise<unknown>;
  /** TS_PREF (resources/js/ui_pref.js): what the user chose on the screen, kept across visits */
  pref: { get: (key: string) => string; set: (key: string, value: string) => void };
  /** #{request.contextPath}: where the BFF is ("" here) */
  ctx: string;
  /**
   * attach the customer suggestions (odsProspectSuggest) to the search field. false = what Java does in practice: open_down_select.js is
   * loaded after this script, so the function does not exist yet when the script looks for it (see tools/sync-receipts.mjs)
   */
  suggestCustomers: boolean;
}

export function startReceipts(env: ReceiptsEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });

                // ★ สิทธิ์ปุ่ม "อนุมัติ" (แถวที่ยังไม่อนุมัติ) — มี key ใดก็ได้ในชุด (hasFeature เป็น OR)
                //   (มี OR ตามที่ user ยืนยัน 05/08 เพราะ session จริงไม่มี key "Approve" แยกต่างหากตามที่ spec เขียนไว้)
                //   ไม่กระทบ badge "อนุมัติแล้ว"/"—" (ไม่ใช่ action คลิกไม่ทำอะไร ดู click handler บรรทัด ~1006)
                //   ★ 11/09: เติม FEATURE_CRM_Document ให้ชุดเดียวกับปุ่มบันทึก/เพิ่มใหม่ และ ROLE_RV_APPROVE
                //   ฝั่ง server — ผู้ใช้ tenant SUN GATEWAY ไม่มี key CRM_RV_* เลย ปุ่มอนุมัติจึงไม่ขึ้นด้วยเหตุผลเดียวกัน
                var RV_CAN_APPROVE = env.can('CRM_RV_View,CRM_RV_Edit,FEATURE_CRM_Document');
                // ===== ข้อมูลจริงจาก backend GET /api/v1/rv (ผ่าน servlet /rvapi ฝั่งเรา) =====
                // สถานะจริงมี 7 ค่า → จัดกลุ่มเป็น wait/done/cancel เพื่อใช้กับ badge + ตัวกรองเดิม
                // ActionWaitProcess = อนุมัติไปแล้วแต่ flow ฝั่ง backend ยังประมวลผลไม่จบ (ปกติ new1 → active1
                //   ทันทีหลังอนุมัติ บางใบค้างสถานะนี้) — ห้ามให้กดอนุมัติซ้ำ ดู rowHtml
                var STATUS_INFO = {
                    active1:    { st: 'done',   label: env.t("label.rv.st_active") },
                    active2:    { st: 'done',   label: env.t("label.rv.st_active") },
                    active:     { st: 'done',   label: env.t("label.rv.st_active") },
                    'new':      { st: 'wait',   label: env.t("label.rv.st_new") },
                    new1:       { st: 'wait',   label: env.t("label.rv.st_new") },
                    waitToFlow: { st: 'wait',   label: env.t("label.rv.st_wait_flow") },
                    ActionWaitProcess: { st: 'wait', label: env.t("label.rv.st_action_wait") },
                    cancel:     { st: 'cancel', label: env.t("chat.cancel") }
                };
                function esc(s) {
                    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
                }
                function fmtDate(iso) {
                    if (!iso) { return '-'; }
                    var p = String(iso).split('-');
                    return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : iso;
                }
                // แปลงข้อมูลจาก API → รูปแถวเดียวกับเอกสารที่สร้างเอง
                /* ★ 11/08: เลขที่เอกสารสำหรับ "พิมพ์ฟอร์ม" ไม่ใช่ตัวเดียวกับ txno ที่โชว์ในตาราง
                   - txno ของ CRM = RV:00-2026-0811-113413-2458 (อยู่แค่ฐาน gwbo)
                   - txno ของ ERP = RV:M13-2607-00057 (อยู่ในฐาน red ที่ระบบรายงาน JasperReports อ่าน)
                   ส่ง txno ของ CRM ไปให้ระบบรายงาน = ได้ฟอร์มเปล่า (หน้ากระดาษ 1 หน้า ไม่มีข้อความ)
                   backend ผูกให้แล้วผ่าน print_forms[].url — ดึงค่า txno ออกมาจาก url นั้น
                   เลือกฟอร์ม RV-01 (RV_01_M13) ก่อน ไม่มีค่อยใช้ฟอร์มแรกที่มี */
                function printTxnoOf(it) {
                    var forms = (it && it.print_forms) || [];
                    if (!forms.length) { return ''; }
                    var f = null;
                    for (var i = 0; i < forms.length; i++) {
                        if (forms[i] && forms[i].code === 'RV_01_M13') { f = forms[i]; break; }
                    }
                    if (!f) { f = forms[0]; }
                    var m = f && f.url ? String(f.url).match(/[?&]txno=([^&]+)/) : null;
                    return m ? decodeURIComponent(m[1]) : '';
                }
                function mapApiRow(it) {
                    var info = STATUS_INFO[it.status] || { st: 'wait', label: it.status || '-' };
                    return {
                        id: it.id,
                        docNo: it.txno || '-',
                        printTxno: printTxnoOf(it),   // เลขที่ฝั่ง ERP — ใช้กับปุ่มพิมพ์ฟอร์มเท่านั้น
                        date: fmtDate(it.txdate),
                        st: info.st,
                        stLabel: info.label,
                        rawSt: it.status || '',   // สถานะดิบจาก backend — ใช้ตัดสินปุ่มอนุมัติ (ActionWaitProcess)
                        /* ★ 11/08: backend เปลี่ยนชื่อฟิลด์ — เดิม created_by/payer ตอนนี้เป็น
                           createbyname/createbycode และ payername/payercode (ชื่อว่างได้ ต้องตกไปใช้รหัส)
                           อ่านชื่อใหม่ก่อน แล้วค่อย fallback ชื่อเดิม ไม่งั้น 2 คอลัมน์นี้ขึ้น "-" ทั้งตาราง */
                        maker: it.createbyname || it.createbycode || it.created_by || '-',
                        payer: it.payername || it.payercode || it.payer || '-',
                        /* เลข Prospect = payer_code (payerCode ผูกกับ prospectCode มาตั้งแต่ตอนสร้าง Lead เสมอ) */
                        prospectNo: it.payercode || it.payer_code || '-',
                        leadNo: '-',   // เติมทีหลังจาก mergeLeadNo() — RV เองไม่เก็บเลข Lead ต้องจับคู่ด้วย prospect code
                        desc: it.description || ''
                    };
                }
                /* จับคู่ "เลข Lead" ด้วย prospect code — RV list/detail API ไม่มีฟิลด์นี้ตรง ๆ
                   ใช้ ../rvapi?action=leads (เอ็นด์พอยต์เดียวกับ picker หน้าสร้าง RV) เป็นแหล่งจับคู่
                   ลูกค้าคนเดียวมีได้หลาย Lead — เอาตัวล่าสุด (backend ส่งเรียงใหม่→เก่า, code แรกที่เจอ) */
                function mergeLeadNo(rows) {
                    return env.fetch('/rvapi?action=leads')
                        .then(function (r) { return r.json(); })
                        .then(function (d) {
                            var items = (d && d.result) || [];
                            var map = {};
                            items.forEach(function (it) {
                                var code = (it.code || '').trim();
                                if (!code || map[code]) { return; }
                                map[code] = it.txNo || '-';
                            });
                            rows.forEach(function (r) { r.leadNo = map[r.prospectNo] || '-'; });
                            return rows;
                        })
                        .catch(function () { return rows; });   // จับคู่ไม่ได้ก็ยังแสดงตารางได้ (leadNo = '-')
                }

                function statusHtml(r) {
                    var label = r.stLabel
                        || (r.st === 'done' ? env.t("label.rv.st_debt_cleared") : (r.st === 'cancel' ? env.t("chat.cancel") : env.t("label.rv.st_new_doc")));
                    return '<span class="sd2-badge ' + r.st + '">' + esc(label) + '</span>';
                }

                function rowHtml(r) {
                    var approveBtn;
                    if (r.st === 'done') {
                        approveBtn = ('<button type="button" class="sd2-approve-btn approved">' + env.t("label.rv.approved") + '</button>');
                    } else if (r.st === 'cancel') {
                        approveBtn = '<span style="color:#9AA0AE;">&#x2014;</span>';
                    } else if (r.rawSt === 'ActionWaitProcess') {
                        // อนุมัติไปแล้ว รอ scheduler — กดซ้ำ backend จะตอบ hopDone=false เปล่า ๆ
                        approveBtn = ('<button type="button" class="sd2-approve-btn approved">' + env.t("label.rv.st_action_wait") + '</button>');
                    } else if (RV_CAN_APPROVE) {
                        approveBtn = ('<button type="button" class="sd2-approve-btn"><i class="fas fa-check"></i> ' + env.t("label.rv.approve") + '</button>');
                    } else {
                        approveBtn = '<span style="color:#9AA0AE;">&#x2014;</span>';
                    }
                    var searchVal = esc((r.docNo + ' ' + r.maker + ' ' + r.payer + ' ' + (r.desc || '') + ' ' + r.prospectNo + ' ' + r.leadNo).toLowerCase());
                    var descHtml = r.desc
                        ? '<td style="color:#5A6473; max-width:220px; overflow:hidden; text-overflow:ellipsis;" title="' + esc(r.desc) + '">' + esc(r.desc) + '</td>'
                        : '<td style="color:#9AA0AE;"><span style="font-size:calc(10px + var(--ts-fs-adj,0px));">&#x2014;</span></td>';
                    var mt = (String(r.docNo).match(/^RV:(M[0-9]+)/) || [])[1] || '';
                    return '<tr data-st="' + r.st + '" data-mt="' + mt + '" data-id="' + (r.id != null ? r.id : '') + '" data-txno="' + esc(r.docNo) + '"'
                        + ' data-print-txno="' + esc(r.printTxno || '') + '" data-s="' + searchVal + '" style="cursor:pointer;">'
                        + '<td>' + esc(r.date) + '</td>'
                        + '<td>' + esc(r.docNo) + '</td>'
                        + '<td>' + statusHtml(r) + '</td>'
                        + '<td style="color:#5A6473;">' + esc(r.maker) + '</td>'
                        + descHtml
                        + '<td style="color:#5A6473;">' + esc(r.payer) + '</td>'
                        + '<td style="color:#5A6473;">' + esc(r.prospectNo) + '</td>'
                        + '<td style="color:#5A6473;">' + esc(r.leadNo) + '</td>'
                        + '<td style="text-align:center;">' + approveBtn + '</td>'
                        + ('<td><button type="button" class="sd2-report"><i class="fas fa-file-alt"></i> ' + env.t("label.rv.report") + '</button></td>')
                        + '</tr>';
                }

                var body = document.getElementById('sd2Body');
                // ★ เลิกผสมเอกสาร mock จาก localStorage (rv_mock_docs) แล้ว — เป็น legacy สมัยฟอร์ม create ยัง mock
                //   (เครื่องที่เคยเทสจะเห็นเอกสารเกินจาก backend) ตอนนี้ตารางแสดงข้อมูลจริงจาก API ล้วน
                // ผลิตภัณฑ์จริงจาก master (movement-types/LD): ชื่อ + usesWorkflowStep
                // mapping ผลิตภัณฑ์ → รหัสเอกสาร RV ตาม design เดิม (A→M13, B→M14, C→M15) — รอยืนยันจาก backend
                var PRODUCT_MT = { 'LD-WFS-A': 'M13', 'LD-WFS-B': 'M14', 'LD-WFS': 'M15' };
                var PRODUCTS = [];
                function loadProducts() {
                    return env.fetch('/rvapi?action=products')
                        .then(function (r) { return r.json(); })
                        .then(function (d) { PRODUCTS = (d && d.result) || []; })
                        .catch(function () { PRODUCTS = []; });
                }
                // dropdown: ทั้งหมด + ผลิตภัณฑ์จริง (มี/ไม่มี WorkFlow Step) เท่านั้น
                function buildProductMenu(data) {
                    var menu = document.getElementById('sd2ProductMenu');
                    if (!menu) { return; }
                    var counts = {};
                    data.forEach(function (r) {
                        var mt = (String(r.docNo).match(/^RV:(M[0-9]+)/) || [])[1];
                        if (mt) { counts[mt] = (counts[mt] || 0) + 1; }
                    });
                    var h = '<div class="sd2-menu-item' + (curMt === '' ? ' active' : '') + ('" data-v="">' + env.t("label.contracts.filter_all") + '</div>');
                    var activeName = '';
                    PRODUCTS.forEach(function (p) {
                        var mt = PRODUCT_MT[p.code];
                        if (!mt) { return; }
                        if (curMt === mt) { activeName = p.name; }
                        h += '<div class="sd2-menu-item' + (curMt === mt ? ' active' : '') + '" data-v="' + mt + '" data-name="' + esc(p.name) + '">'
                           + esc(p.name) + ' <span style="color:#9AA0AE;font-weight:400;">(' + (counts[mt] || 0) + (' ' + env.t("label.rv.count_unit") + ')</span></div>');
                    });
                    menu.innerHTML = h;
                    // ป้ายปุ่ม (sd2ProductVal) ต้องตรงกับตัวกรองที่ใช้งานจริงเสมอ — sync ทุกครั้งที่ build เมนู
                    // (รวมถึงตอนโหลดหน้าครั้งแรกที่ curMt มาจากค่าที่จำไว้ ไม่ใช่แค่ตอนผู้ใช้กดเลือกเอง)
                    var valEl = document.getElementById('sd2ProductVal');
                    if (valEl) { valEl.textContent = curMt ? (activeName || curMt) : env.t("label.contracts.filter_all"); }
                }
                // ---------- การเรียงลำดับ (sort) ----------
                var sd2Data = [];                       // ข้อมูลทั้งหมดที่โหลดมา (ก่อนเรียง)
                var sd2SortKey = null, sd2SortDir = 1;  // dir: 1 = น้อย→มาก, -1 = มาก→น้อย
                function sd2SortVal(r, key) {
                    if (key === 'date') {
                        var p = String(r.date || '').split('/');   // dd/mm/yyyy → yyyymmdd เพื่อเทียบ
                        return p.length === 3 ? (p[2] + p[1] + p[0]) : '';
                    }
                    return String(r[key] == null ? '' : r[key]).toLowerCase();
                }
                function sd2Sorted(data) {
                    if (!sd2SortKey) { return data; }
                    var key = sd2SortKey, dir = sd2SortDir;
                    return data.slice().sort(function (a, b) {
                        return sd2SortVal(a, key).localeCompare(sd2SortVal(b, key), 'th', { numeric: true }) * dir;
                    });
                }
                function sd2BuildBody(data) {
                    var html = '';
                    for (var i = 0; i < data.length; i++) { html += rowHtml(data[i]); }
                    body.innerHTML = html || ('<tr><td colspan="10" style="text-align:center; color:#9AA0AE; padding:28px;">' + env.t("label.dashboard.no_data") + '</td></tr>');
                }
                function sd2UpdateSortIcons() {
                    var ths = document.querySelectorAll('.sd2-table thead th.sd2-sortable');
                    for (var i = 0; i < ths.length; i++) {
                        var th = ths[i], ic = th.querySelector('.sd2-sort-ic');
                        var active = th.getAttribute('data-sort') === sd2SortKey;
                        th.classList.toggle('sorted', active);
                        if (ic) { ic.className = 'fas sd2-sort-ic ' + (active ? (sd2SortDir < 0 ? 'fa-sort-down' : 'fa-sort-up') : 'fa-sort'); }
                    }
                }
                function renderRows(data) {
                    sd2Data = data.slice();
                    sd2BuildBody(sd2Sorted(sd2Data));
                    buildProductMenu(sd2Data);
                    sd2UpdateSortIcons();
                    applyFilters();
                }
                (function () {
                    var thead = document.querySelector('.sd2-table thead');
                    if (!thead) { return; }
                    thead.addEventListener('click', function (e) {
                        var th = e.target.closest('th.sd2-sortable');
                        if (!th) { return; }
                        var key = th.getAttribute('data-sort');
                        if (sd2SortKey === key) { sd2SortDir = -sd2SortDir; } else { sd2SortKey = key; sd2SortDir = 1; }
                        sd2BuildBody(sd2Sorted(sd2Data));
                        sd2UpdateSortIcons();
                        applyFilters();
                    });
                })();
                // โหลดผลิตภัณฑ์ + ข้อมูลจริงทั้งหมดจาก backend
                // ★ 03/09: เดิม loadProducts() → รอเสร็จค่อย env.fetch(list) เรียงกัน (3 round-trip: products → list →
                //   mergeLeadNo) ทั้งที่ list ไม่ได้ใช้ผลของ PRODUCTS เลย (PRODUCTS ใช้แค่ตอน buildProductMenu()
                //   ซึ่งเรียกทีหลังจาก renderRows() อยู่แล้ว) → ยิงขนานแทนด้วย Promise.all ตัดรอบที่เสียเปล่าออก
                //   1 รอบ mergeLeadNo() ยังคงทำทีหลังเหมือนเดิม (ต้องรู้ rows ก่อนถึงจะจับคู่เลข Lead ได้จริง)
                function renderTable() {
                    if (!body) { return; }
                    body.innerHTML = ('<tr><td colspan="10" style="text-align:center; color:#9AA0AE; padding:28px;">' + env.t("label.rv.loading_data") + '</td></tr>');
                    Promise.all([
                        loadProducts(),
                        env.fetch('/rvapi?action=list&page=1&pageSize=500').then(function (resp) { return resp.json(); })
                    ])
                        .then(function (arr) {
                            var d = arr[1];
                            var items = ((d && d.result) || {}).items || [];
                            var rows = items.map(mapApiRow);
                            renderRows(rows);          // แสดงตารางก่อนเลย (คอลัมน์เลข Lead ยังเป็น "-")
                            return mergeLeadNo(rows);   // จับคู่เลข Lead ทีหลัง ไม่บล็อกการแสดงผลหลัก
                        })
                        .then(function (rows) {
                            if (rows) { renderRows(rows); }   // อัปเดตอีกรอบพร้อมเลข Lead (คง sort/filter เดิมผ่าน renderRows ปกติ)
                        })
                        .catch(function (e) {
                            body.innerHTML = ('<tr><td colspan="10" style="text-align:center; color:#EB5050; padding:28px;">' + env.t("label.rv.load_fail") + ' ') + esc(e) + '</td></tr>';
                        });
                }
                if (body) { renderTable(); }

                // ---------- utilities ----------
                /* ★ 21/08: user ขอให้ toast มุมล่างกลางจอเปลี่ยนเป็นแจ้งเตือนกลางจอแบบ swal ทั้งระบบ */
                function toast(msg) {
                    env.swal({ text: msg, icon: 'info', timer: 2500, buttons: false });
                }
                /* ---------- ข้อมูลใบรับเงิน: ตัวอ่านชุดเดียวที่ใช้ร่วมกันทุกที่ที่แสดงใบรับเงินในหน้านี้ ----------
                   (modal "รายละเอียดใบรับเงิน" + รูปภาพใบเสร็จบน canvas — ฝั่ง server ก็เอาชุดเดียวกันไปทำ PDF)

                   ★ ฟิลด์ที่ใช้ตรงนี้ถูก normalize มาจาก Service layer แล้ว (RvDetailNormalizer เรียกจาก
                     RvApiService.detailJson) การันตีว่ามี currency_symbol / remark /
                     payment_items[].amount + .amount_available เสมอ — หน้าเว็บไม่ต้องรู้ว่า backend
                     ตั้งชื่อฟิลด์ว่าอะไร และไม่ต้องไล่แก้หลายจุดเวลา backend เปลี่ยนชื่อ (CLAUDE.md ข้อ 3) */
                function rvMoney(n) {
                    var v = parseFloat(n);
                    if (!isFinite(v)) { v = 0; }
                    return v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                }
                /* สกุลเงินของใบนี้ — ใบสกุลอื่นได้ "USD " นำหน้าแทน ฿ (เดิม hardcode ฿ ทุกยอด) */
                function rvCurrency(res) { return (res && res.currency_symbol) || '฿'; }
                function rvAmountText(res, n) { return rvCurrency(res) + rvMoney(n); }
                /* รายการรับชำระพร้อมข้อความที่แสดงได้เลย — backend ไม่ส่งจำนวนเงินมาให้ขึ้น "—"
                   ไม่ใช่ ฿0.00 เพราะ "ไม่มีข้อมูล" กับ "ศูนย์บาทจริง" คนละความหมาย */
                function rvPayLines(res) {
                    return ((res && res.payment_items) || []).map(function (p) {
                        return {
                            name: p.receivemethodname || p.receivemethodcode || '-',
                            amountText: (p.amount_available === false) ? '—' : rvAmountText(res, p.amount)
                        };
                    });
                }
                /* รายการสินค้าในใบรับเงิน
                   ★ 24/08: detail API **คืน material_items มาให้จริง** (ยืนยันจาก response ใน API log)
                     คอมเมนต์เดิมทั้งไฟล์ที่เขียนว่า "detail API ไม่คืนรายการ" จึงล้าสมัย — เดิมต้องกดปุ่ม
                     "ฟอร์มใบเสร็จ (PDF)" ออกไปดูที่ระบบรายงานถึงจะเห็นรายการ ตอนนี้ดูใน modal ได้เลย
                   แต่ละรายการ backend ส่ง: materialcode, materialname, detail, amount(ก่อนภาษี),
                     tax_percent, netamount_before_vat, vat_amount, netamount_after_vat
                   โชว์ชื่อ + ยอดรวมภาษีของรายการนั้น (ตรงกับยอดสุทธิของบิลเมื่อรวมกัน) */
                function rvItemsHtml(res) {
                    var items = (res && res.material_items) || [];
                    if (!items.length) { return ''; }
                    return ('<div class="sd2-dt-sec">' + env.t("label.rv.detail_items") + '</div>')
                        + items.map(function (it) {
                            var name = it.materialname || it.materialcode || '-';
                            var note = (it.detail || '').trim();
                            return '<div class="sd2-dt-pay">'
                                + '<span style="padding-right:12px;">' + esc(name)
                                + (note ? '<br/><span style="color:#8A92A6; font-size:calc(11px + var(--ts-fs-adj,0px));">' + esc(note) + '</span>' : '')
                                + '</span>'
                                + '<span style="white-space:nowrap;">' + esc(rvAmountText(res, it.netamount_after_vat)) + '</span>'
                                + '</div>';
                        }).join('');
                }

                // ---------- พรีวิว/พิมพ์ใบรับเงิน — PDF ใช้ไฟล์ PDF จริงจาก server (RvReceiptPdfServlet), รูปภาพวาดจาก canvas ----------
                var pendingReportId = '';   // set ตอนกดปุ่ม "รายงาน" ในแถว — ใช้ตอนกด PDF/รูปภาพ ใน popover
                var pendingReportTxno = ''; // เลขที่เอกสาร (txno) ของแถวเดียวกัน — ใช้เปิดฟอร์ม RV-01 จากระบบรายงานเดิม
                /* วาดใบรับเงินลง canvas แล้วเปิดเป็นไฟล์รูปภาพล้วน ๆ (ไม่มี toolbar/ปุ่ม — ต่างจาก PDF ที่เป็นไฟล์ PDF จริง) */
                function openReceiptImage(res) {
                    var pays = rvPayLines(res);
                    var rowH = 26, headerH = 130, infoH = 90, tableHeadH = 30, totalsH = 130;
                    var tableRowsH = Math.max(pays.length, 1) * rowH;
                    var remarkH = res.remark ? 30 : 0;
                    var W = 800, padTop = 30, padBottom = 30;
                    var H = padTop + headerH + infoH + tableHeadH + tableRowsH + totalsH + remarkH + padBottom;
                    var x = 40, rightX = W - 40;

                    var c = document.createElement('canvas');
                    c.width = W; c.height = H;
                    var ctx = c.getContext('2d');
                    var THFONT = '"Noto Sans Thai","Leelawadee UI",sans-serif';

                    ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, W, H);
                    ctx.fillStyle = '#35236A'; ctx.fillRect(0, 0, W, 8);

                    var y = padTop + 20;
                    ctx.textAlign = 'left';
                    ctx.fillStyle = '#1F2430'; ctx.font = '700 18px ' + THFONT;
                    ctx.fillText('บริษัท แอคชีฟเวอร์ จำกัด', x, y);
                    ctx.fillStyle = '#6B7280'; ctx.font = '12px ' + THFONT;
                    ctx.fillText('ACHIEVER CO., LTD.', x, y + 18);

                    var boxW = 200, boxH = 50, boxX = rightX - boxW, boxY = padTop;
                    ctx.fillStyle = '#F3F4F6'; ctx.fillRect(boxX, boxY, boxW, boxH);
                    ctx.textAlign = 'center';
                    ctx.fillStyle = '#1F2430'; ctx.font = '700 16px ' + THFONT;
                    ctx.fillText('ใบรับเงิน', boxX + boxW / 2, boxY + 22);
                    ctx.fillStyle = '#6B7280'; ctx.font = '11px ' + THFONT;
                    ctx.fillText('Receipt', boxX + boxW / 2, boxY + 38);
                    ctx.textAlign = 'left';

                    var lineY = padTop + headerH - 10;
                    ctx.strokeStyle = '#35236A'; ctx.lineWidth = 2;
                    ctx.beginPath(); ctx.moveTo(x, lineY); ctx.lineTo(rightX, lineY); ctx.stroke();

                    var infoY = lineY + 24, col2X = x + (rightX - x) / 2;
                    function infoCell(cx, cy, label, val) {
                        ctx.fillStyle = '#6B7280'; ctx.font = '11px ' + THFONT; ctx.fillText(label, cx, cy);
                        ctx.fillStyle = '#1F2430'; ctx.font = '700 13px ' + THFONT; ctx.fillText(String(val), cx, cy + 16);
                    }
                    infoCell(x, infoY, 'เลขที่เอกสาร', res.txno || '-');
                    infoCell(col2X, infoY, 'วันที่เอกสาร', fmtDate(res.txdate) || '-');
                    infoCell(x, infoY + 40, 'ผู้ชำระเงิน', res.payer_name || res.payer_code || '-');
                    infoCell(col2X, infoY + 40, 'สกุลเงิน', res.currency_code || '-');

                    var tableY = infoY + 40 + 40;
                    ctx.fillStyle = '#F3F4F6'; ctx.fillRect(x, tableY, rightX - x, tableHeadH);
                    ctx.fillStyle = '#1F2430'; ctx.font = '700 12px ' + THFONT;
                    ctx.fillText('วิธีการชำระเงิน', x + 10, tableY + 20);
                    ctx.textAlign = 'right'; ctx.fillText('จำนวนเงิน', rightX - 10, tableY + 20); ctx.textAlign = 'left';

                    var rowY = tableY + tableHeadH;
                    if (pays.length) {
                        pays.forEach(function (p) {
                            ctx.strokeStyle = '#F3F4F6'; ctx.beginPath(); ctx.moveTo(x, rowY + rowH); ctx.lineTo(rightX, rowY + rowH); ctx.stroke();
                            ctx.fillStyle = '#3A4051'; ctx.font = '13px ' + THFONT;
                            ctx.fillText(p.name, x + 10, rowY + 18);
                            ctx.textAlign = 'right'; ctx.fillText(p.amountText, rightX - 10, rowY + 18); ctx.textAlign = 'left';
                            rowY += rowH;
                        });
                    } else {
                        ctx.fillStyle = '#9CA3AF'; ctx.font = '12px ' + THFONT;
                        ctx.fillText('— ไม่มีข้อมูลการรับชำระ —', x + 10, rowY + 18);
                        rowY += rowH;
                    }

                    var totY = rowY + 24, totW = 260, totX = rightX - totW;
                    function totalLine(label, val, bold) {
                        ctx.fillStyle = '#3A4051'; ctx.font = (bold ? '700 ' : '') + '13px ' + THFONT;
                        ctx.fillText(label, totX, totY);
                        ctx.textAlign = 'right'; ctx.fillText(val, rightX, totY); ctx.textAlign = 'left';
                        totY += 22;
                    }
                    totalLine('ยอดก่อนภาษี', rvAmountText(res, res.netamount_before_vat));
                    totalLine('ภาษีมูลค่าเพิ่ม', rvAmountText(res, res.vat_amount));
                    totalLine('ยอดสุทธิ', rvAmountText(res, res.netamount_after_vat));
                    ctx.strokeStyle = '#1F2430'; ctx.beginPath(); ctx.moveTo(totX, totY - 6); ctx.lineTo(rightX, totY - 6); ctx.stroke();
                    totalLine('ยอดชำระ', rvAmountText(res, res.pay_amount), true);

                    if (res.remark) {
                        ctx.fillStyle = '#3A4051'; ctx.font = '12px ' + THFONT;
                        ctx.fillText('หมายเหตุ: ' + res.remark, x, totY + 14);
                    }

                    if (!c.toBlob) { toast(env.t("label.rv.img_not_supported")); return; }
                    c.toBlob(function (b) {
                        if (!b) { toast(env.t("label.rv.img_fail")); return; }
                        var url = URL.createObjectURL(b);
                        env.open(url, '_blank');
                        window.setTimeout(function () { URL.revokeObjectURL(url); }, 60000);
                    }, 'image/png');
                }
                function openReceiptPreview(id, type) {
                    if (!id && !pendingReportTxno) { toast(env.t("label.rv.no_id_report")); return; }
                    if (type !== 'img') {
                        // ★ PDF = ฟอร์มใบเสร็จรับเงินจริง RV-01 จากระบบรายงานเดิม (JasperReports) ผ่าน proxy /rvreport
                        if (pendingReportTxno) {
                            env.open('/rvreport?txno=' + encodeURIComponent(pendingReportTxno), '_blank');
                            return;
                        }
                        /* ★ 11/09: ไม่มีเลขที่ฝั่ง ERP = ใบนี้ยังไม่ sync เข้า ERP (erpSynced:false → print_forms ว่าง)
                           เดิมตกไปส่งเลขที่ของ CRM ให้ Jasper ซึ่ง "ไม่มีวันเจอ" เพราะ Jasper อ่าน MySQL red ส่วนเลข CRM
                           อยู่แค่ postgres gwbo — ผลคือได้ PDF 1 หน้าเปล่าแบบ HTTP 200 ไม่มี error ผู้ใช้ไม่รู้สาเหตุ
                           (พิสูจน์ 11/09: เลข CRM ได้ 1,218 bytes เทียบกับเลข ERP 92,468 bytes)
                           ⇒ เลิกเดา: บอกเหตุผลตรง ๆ แล้วเปิดพรีวิวจากข้อมูลจริงใน o2o (/rvreceipt) แทน */
                        toast(env.t("label.rv.not_synced_erp_preview"));
                        env.open('/rvreceipt?id=' + encodeURIComponent(id), '_blank');
                        return;
                    }
                    // ★ รูปภาพ = ฟอร์ม RV-01 จริงแปลงเป็น PNG ฝั่ง server (/rvreport&format=png ผ่าน PDFBox)
                    if (pendingReportTxno) {
                        env.open('/rvreport?txno=' + encodeURIComponent(pendingReportTxno) + '&format=png', '_blank');
                        return;
                    }
                    // ยังไม่ sync เข้า ERP → วาดใบรับเงินจากข้อมูล detail แทนฟอร์ม RV-01 (เหตุผลเดียวกับฝั่ง PDF ด้านบน)
                    toast(env.t("label.rv.not_synced_erp_preview"));
                    env.fetch('/rvapi?action=detail&id=' + encodeURIComponent(id))
                        .then(function (r) { return r.json(); })
                        .then(function (d) {
                            var res = d && d.result;
                            if (!res || !res.txno) { toast(env.t("label.rv.no_data_report")); return; }
                            openReceiptImage(res);
                        })
                        .catch(function () { toast(env.t("label.rv.load_report_fail")); });
                }

                // ---------- popovers / menus ----------
                var pop = document.getElementById('sd2Pop');
                var itemsPop = document.getElementById('sd2Items');

                var filterMenu = document.getElementById('sd2FilterMenu');
                function closeAll() {
                    [pop, itemsPop, document.getElementById('sd2ProductMenu'), filterMenu].forEach(function (el) { if (el) { el.classList.remove('show'); } });
                }
                function openPopAt(el, anchor, w) {
                    var r = anchor.getBoundingClientRect();
                    var left = r.right - w;
                    if (left < 8) { left = 8; }
                    el.style.top = (r.bottom + 6) + 'px';
                    el.style.left = left + 'px';
                    closeAll();
                    el.classList.add('show');
                }

                // ---------- ค้นหา + ตัวกรองสถานะ ----------
                var searchWrap = document.getElementById('sd2Search');
                var searchIc = document.getElementById('sd2SearchBtn');
                var searchInput = document.getElementById('sd2SearchInput');
                var searchGo = document.getElementById('sd2SearchGo');
                var searchClr = document.getElementById('sd2SearchClear');
                var curFilter = 'all';
                /* ★ 18/08: จำตัวกรองผลิตภัณฑ์ไว้ — รีเฟรชหน้าแล้วไม่ต้องเลือกใหม่ทุกครั้ง
                   (แพตเทิร์นเดียวกับหน้าแดชบอร์ด/การติดต่อ — ค่าเป็นรหัสเอกสาร M13/M14/M15 ที่ตายตัวอยู่แล้วใน PRODUCT_MT)
                   ★ 19/08: เก็บผ่าน TS_PREF (ui_pref.js = localStorage + cookie) แทน localStorage ตรง ๆ
                   ค่าจะได้อยู่ข้ามการปิดเบราว์เซอร์/login ใหม่ด้วย ไม่ใช่แค่ข้ามการรีเฟรช */
                var SD2_MT_STORAGE_KEY = 'ts_rvlist_selected_mt';
                function sd2SaveMt(v) { env.pref.set(SD2_MT_STORAGE_KEY, v || ''); }
                function sd2LoadSavedMt() { return env.pref.get(SD2_MT_STORAGE_KEY); }
                var curMt = sd2LoadSavedMt();   // กรองตามรหัสประเภทเอกสาร (M12, M13, ...) จาก dropdown ผลิตภัณฑ์
                function applyFilters() {
                    if (!body) { return; }
                    var q = ((searchInput && searchInput.value) || '').trim().toLowerCase();
                    var rows = body.querySelectorAll('tr');
                    var shown = 0;
                    rows.forEach(function (tr) {
                        var matchS = !q || (tr.getAttribute('data-s') || '').indexOf(q) !== -1;
                        var matchF = (curFilter === 'all') || (tr.getAttribute('data-st') === curFilter);
                        var matchM = !curMt || (tr.getAttribute('data-mt') === curMt);
                        var vis = matchS && matchF && matchM;
                        tr.style.display = vis ? '' : 'none';
                        if (vis) { shown++; }
                    });
                    var foot = document.querySelector('.sd2-foot span');
                    if (foot) { foot.textContent = env.t("label.rv.showing").replace('{0}', shown).replace('{1}', rows.length); }
                }
                /* ★ 18/09: เปลี่ยนช่องค้นหาจากไอคอนสลับ (แว่นขยาย ↔ กากบาท) มาใช้ pill ขยาย + ปุ่ม "ค้นหา"
                   แบบเดียวกับหน้าลูกค้าเป้าหมาย (contracts.xhtml) — เหมือนกันทั้งระบบ */
                function sd2OpenSearch() { if (searchWrap) { searchWrap.classList.add('open'); } if (searchInput) { searchInput.focus(); } }
                function sd2CloseSearch() {
                    if (searchWrap) { searchWrap.classList.remove('open'); }
                    if (searchInput) { searchInput.value = ''; }
                    applyFilters();
                }
                if (searchIc) {
                    searchIc.addEventListener('click', function (e) {
                        e.stopPropagation();
                        if (searchWrap && searchWrap.classList.contains('open')) { if (searchInput) { searchInput.focus(); } }
                        else { sd2OpenSearch(); }
                    });
                }
                if (searchGo) { searchGo.addEventListener('click', function (e) { e.stopPropagation(); applyFilters(); }); }
                if (searchClr) { searchClr.addEventListener('click', function (e) { e.stopPropagation(); sd2CloseSearch(); }); }
                if (searchInput) {
                    searchInput.addEventListener('input', applyFilters);
                    searchInput.addEventListener('keydown', function (e) {
                        if (e.key === 'Enter') { e.preventDefault(); applyFilters(); }
                        else if (e.key === 'Escape') { sd2CloseSearch(); }
                    });
                    /* ★ 18/09: การ์ดแนะนำลูกค้าใต้ช่องค้นหา (component กลาง odsProspectSuggest, open_down_select.js)
                       เลือกแล้วใส่ชื่อลงช่อง + เรียก applyFilters() กรองแถวที่โหลดมาแล้วทันที (เหมือนพิมพ์เอง) */
                    if (env.suggestCustomers && window.odsProspectSuggest) {
                        window.odsProspectSuggest(searchInput, {
                            contextPath: env.ctx,
                            fetch: env.fetch,
                            onPick: function (item) {
                                searchInput.value = item && item.value ? item.value : searchInput.value;
                                applyFilters();
                            }
                        });
                    }
                }


                // ---------- ดรอปดาวน์ผลิตภัณฑ์/ประเภทเอกสาร (รายการจริงจากข้อมูล) ----------
                var prodBtn = document.getElementById('sd2ProductBtn');
                var productMenu = document.getElementById('sd2ProductMenu');
                if (prodBtn) {
                    prodBtn.addEventListener('click', function (e) {
                        e.stopPropagation();
                        var willOpen = !productMenu.classList.contains('show');
                        closeAll();
                        if (willOpen) { productMenu.classList.add('show'); }
                    });
                    productMenu.addEventListener('click', function (e) {
                        var it = e.target.closest('.sd2-menu-item'); if (!it) { return; }
                        e.stopPropagation();
                        productMenu.querySelectorAll('.sd2-menu-item').forEach(function (m) { m.classList.remove('active'); });
                        it.classList.add('active');
                        curMt = it.getAttribute('data-v') || '';
                        sd2SaveMt(curMt);
                        var prodName = it.getAttribute('data-name');
                        document.getElementById('sd2ProductVal').textContent = curMt ? (prodName || curMt) : env.t("label.contracts.filter_all");
                        productMenu.classList.remove('show');
                        applyFilters();
                    });
                }

                // ---------- ดรอปดาวน์ตัวกรอง ----------
                var filterBtn = document.getElementById('sd2FilterBtn');
                if (filterBtn) {
                    filterBtn.addEventListener('click', function (e) {
                        e.stopPropagation();
                        var willOpen = !filterMenu.classList.contains('show');
                        closeAll();
                        if (willOpen) { filterMenu.classList.add('show'); }
                    });
                    filterMenu.addEventListener('click', function (e) {
                        var it = e.target.closest('.sd2-menu-item'); if (!it) { return; }
                        e.stopPropagation();
                        filterMenu.querySelectorAll('.sd2-menu-item').forEach(function (m) { m.classList.remove('active'); });
                        it.classList.add('active');
                        curFilter = it.getAttribute('data-f');
                        filterMenu.classList.remove('show');
                        applyFilters();
                    });
                }

                // ---------- ปุ่มอนุมัติ → dialog ----------
                var overlay = document.getElementById('sd2Overlay');
                var dialogConfirm = document.getElementById('sd2DialogConfirm');
                var dialogCancel = document.getElementById('sd2DialogCancel');
                var dialogClose = document.getElementById('sd2DialogClose');
                var debtFormat = document.getElementById('sd2DebtFormat');
                var pendingTr = null;

                function closeDialog() {
                    overlay.classList.remove('show');
                    pendingTr = null;
                    if (debtFormat) { debtFormat.value = ''; }
                    if (dialogConfirm) { dialogConfirm.disabled = true; }
                }

                /* จัด dialog อนุมัติให้กลางจอเป๊ะ — measure-and-correct (ชนะ ancestor transform ของ .layout-main) */
                function centerApproveModal() {
                    if (!overlay || !overlay.classList.contains('show')) { return; }
                    var dlg = overlay.querySelector('.sd2-dialog');
                    if (!dlg) { return; }
                    dlg.style.transform = 'none';
                    var r = dlg.getBoundingClientRect();
                    if (!r.width) { return; }
                    var dx = Math.round((window.innerWidth - r.width) / 2 - r.left);
                    var dy = Math.round((window.innerHeight - r.height) / 2 - r.top);
                    dlg.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
                }
                function centerApproveSoon() {
                    if (window.requestAnimationFrame) { requestAnimationFrame(centerApproveModal); } else { tmo(centerApproveModal, 0); }
                }
                listen(window, 'resize', centerApproveModal);

                // เปิด dialog เมื่อกดปุ่มอนุมัติ (เฉพาะแถวที่ยังไม่ได้อนุมัติ)
                listen(document, 'click', function (e) {
                    var btn = e.target.closest('.sd2-approve-btn');
                    if (!btn) { return; }
                    e.stopPropagation();
                    if (btn.classList.contains('approved')) { return; }
                    var tr = btn.closest('tr');
                    if (!tr) { return; }
                    pendingTr = tr;
                    if (debtFormat) { debtFormat.value = ''; }
                    if (dialogConfirm) { dialogConfirm.disabled = true; }
                    // ย้าย overlay ไป <body> — หลุดจาก .layout-main ที่มี transform (containing block ของ position:fixed)
                    if (overlay.parentNode !== document.body) { document.body.appendChild(overlay); }
                    overlay.classList.add('show');
                    centerApproveSoon();
                }, true);

                // เปิดใช้ปุ่มตกลงเมื่อเลือก dropdown แล้ว
                if (debtFormat) {
                    debtFormat.addEventListener('change', function () {
                        if (dialogConfirm) {
                            dialogConfirm.disabled = !debtFormat.value;
                        }
                    });
                }

                // ปิด dialog เมื่อคลิกพื้นหลัง / ปุ่มยกเลิก / X
                if (overlay) {
                    overlay.addEventListener('click', function (e) {
                        if (e.target === overlay) { closeDialog(); }
                    });
                }
                if (dialogCancel) { dialogCancel.addEventListener('click', closeDialog); }
                if (dialogClose) { dialogClose.addEventListener('click', closeDialog); }

                /* ยืนยันอนุมัติ → POST /rvapi?action=approve&txno=... (backend /api/v1/rv/approve)
                   ★ backend คืน HTTP 200 เสมอ ผลจริงอยู่ใน result:{result, status, hopDone, message}
                     - result=false / status!=200 → ไม่สำเร็จ (เช่น 404 ไม่พบ process instance)
                     - result=true + hopDone=false → ยังไม่ได้อนุมัติจริง (สถานะยังไม่ถึง new1 รอ scheduler
                       ดัน new→new1 หรืออนุมัติไปแล้ว) — ห้ามโชว์ว่าสำเร็จ ต้องยกข้อความ backend มาบอกตรง ๆ
                     - result=true + hopDone=true → อนุมัติสำเร็จ → โหลดตารางใหม่ให้สถานะตรงกับ backend
                       (ทดสอบ 06/08: สถานะเปลี่ยน new1 → active1 ทันที)
                   หมายเหตุ: dropdown "รูปแบบเงื่อนไข" เป็นเงื่อนไขของฟอร์มฝั่งหน้าจอ endpoint อนุมัติ
                   รับแค่ txno จึงไม่ได้ส่งค่านี้ไป backend */
                if (dialogConfirm) {
                    dialogConfirm.addEventListener('click', function () {
                        if (!pendingTr || !debtFormat || !debtFormat.value) { return; }
                        var txno = pendingTr.getAttribute('data-txno') || '';
                        var rowBtn = pendingTr.querySelector('.sd2-approve-btn');
                        if (!txno) { closeDialog(); toast(env.t("label.rv.approve_failed")); return; }
                        closeDialog();
                        if (rowBtn) { rowBtn.disabled = true; rowBtn.textContent = env.t("label.rv.approving"); }
                        var httpStatus = 0;
                        env.fetch('/rvapi?action=approve&txno=' + encodeURIComponent(txno), {
                            method: 'POST', credentials: 'same-origin'
                        })
                            .then(function (resp) {
                                httpStatus = resp.status;
                                return resp.json().catch(function () { return {}; });
                            })
                            .then(function (d) {
                                // 403 = servlet ปฏิเสธเพราะไม่มี CRM_RV_View/CRM_RV_Edit (กันคนยิง /rvapi ตรง
                                // ทั้งที่ปุ่มถูกซ่อน) — โชว์เหตุผลจริง ไม่ปนกับ "อนุมัติไม่สำเร็จ" ทั่วไป
                                if (httpStatus === 403) {
                                    toast(env.t("label.rv.approve_no_permission"));
                                    renderTable();
                                    return;
                                }
                                var inner = (d && d.result) || {};
                                var msg = inner.message || d.message || '';
                                var ok = inner.result !== false && Number(inner.status || d.status) === 200 && inner.hopDone === true;
                                if (ok) {
                                    toast(env.t("label.rv.approve_success") + (inner.txno ? ' : ' + inner.txno : ''));
                                    renderTable();   // อ่านสถานะจริงกลับมาใหม่ ไม่เดาเอง
                                } else {
                                    toast(msg || env.t("label.rv.approve_failed"));
                                    renderTable();
                                }
                            })
                            .catch(function (e) {
                                console.error('[rv] approve failed', e);
                                toast(env.t("label.rv.approve_failed"));
                                renderTable();
                            });
                    });
                }

                // ---------- ปุ่มเพิ่มใหม่ ----------
                var addBtn = document.getElementById('sd2AddBtn');
                if (addBtn) { addBtn.addEventListener('click', function () { env.navigate("/sales/receipts/new"); }); }

                // ---------- modal รายละเอียด (GET /rvapi?action=detail&id=) ----------
                var detailOverlay = document.getElementById('sd2DetailOverlay');
                var detailBody = document.getElementById('sd2DetailBody');
                function dtCell(k, v) { return '<div class="sd2-dt-cell"><div class="k">' + esc(k) + '</div><div class="v">' + esc(String(v == null || v === '' ? '-' : v)) + '</div></div>'; }
                var sd2DtTxno = '';   // เลขที่เอกสารของ modal ที่เปิดอยู่ (ฝั่ง CRM) — ใช้แสดงผล
                /* ★ เลขที่ฝั่ง ERP ของ modal ที่เปิดอยู่ — ใช้กับปุ่ม "ฟอร์มใบเสร็จ (PDF)" เท่านั้น
                   ตั้งค่าตอนกดแถว/ปุ่มแว่นขยาย เพราะ detail API ไม่คืน print_forms มาให้ (มีแต่ list) */
                var sd2DtPrintTxno = '';
                function renderDetail(res) {
                    if (!res || !res.txno) { sd2DtTxno = ''; detailBody.innerHTML = ('<div class="sd2-dt-empty">' + env.t("label.rv.detail_not_found") + '</div>'); return; }
                    sd2DtTxno = res.txno;
                    /* ★ 24/08: รายการรับชำระโชว์จำนวนเงินเป็นตัวเลข + บรรทัดเงินทอน ตามที่ user สั่ง
                       จำนวนเงินเพิ่งอ่านได้จริงหลังรู้ว่า backend ใช้ชื่อฟิลด์ medium_amount (ดู RvDetailNormalizer)
                       เงินทอน/ผลรวมคิดมาจากฝั่ง server แล้ว หน้าเว็บแค่หยิบมาแสดง */
                    var pays = rvPayLines(res);
                    var payHtml = pays.length
                        ? pays.map(function (p) { return '<div class="sd2-dt-pay"><span>' + esc(p.name) + '</span><span>' + esc(p.amountText) + '</span></div>'; }).join('')
                        : ('<div style="color:#9AA0AE; font-size:calc(12px + var(--ts-fs-adj,0px)); padding:6px 0;">' + env.t("label.rv.no_payments") + '</div>');
                    // มีหลายวิธีชำระ = โชว์ยอดรวมที่รับมาด้วย วิธีเดียวไม่ต้องโชว์ซ้ำกับบรรทัดบน
                    if (pays.length > 1) {
                        payHtml += ('<div class="sd2-dt-pay"><span>' + env.t("label.rv.received_total") + '</span><span>')
                            + esc(rvAmountText(res, res.payments_total)) + '</span></div>';
                    }
                    if (Number(res.change_amount) > 0) {
                        payHtml += ('<div class="sd2-dt-pay" style="font-weight:600;"><span>' + env.t("label.rv.change_amount") + '</span><span>')
                            + esc(rvAmountText(res, res.change_amount)) + '</span></div>';
                    }
                    detailBody.innerHTML =
                        '<div class="sd2-dt-grid">'
                        + dtCell(env.t("label.sd.doc_no"), res.txno)
                        + dtCell(env.t("label.sd.doc_date"), fmtDate(res.txdate))
                        /* ★ 2 เลขนี้กรอกได้ตอนสร้างใบ แต่เดิมไม่เคยโชว์ในรายละเอียดเลย */
                        + dtCell(env.t("label.sd.ref_doc_no"), res.reference_docno)
                        + dtCell(env.t("label.rv.tax_invoice_no"), res.taxinvoice_txno)
                        + dtCell(env.t("label.rv.payer"), res.payer_name || res.payer_code)
                        + dtCell(env.t("label.rv.currency"), res.currency_code)
                        + dtCell(env.t("label.rv.amount_before_vat"), rvAmountText(res, res.netamount_before_vat))
                        + dtCell(env.t("label.rv.vat"), rvAmountText(res, res.vat_amount))
                        + dtCell(env.t("label.rv.net_amount"), rvAmountText(res, res.netamount_after_vat))
                        + dtCell(env.t("label.rv.pay_amount"), rvAmountText(res, res.pay_amount))
                        /* ★ โชว์ตลอดแม้ค่าว่าง (dtCell ใส่ "-" ให้) ผู้ใช้จะได้รู้ว่ามีช่องนี้อยู่ */
                        + dtCell(env.t("label.rv.col_desc"), res.description)
                        + dtCell(env.t("label.template.remark"), res.remark)
                        + '</div>'
                        + rvItemsHtml(res)
                        + ('<div class="sd2-dt-sec">' + env.t("label.rv.payments_sec") + '</div>') + payHtml;
                }
                /* วางกล่อง detail ให้กลางจอเป๊ะ — measure-and-correct (ชนะ ancestor transform ของ .layout-main
                   ที่ทำให้ position:fixed เกาะมุมซ้ายบนแทน viewport) getBoundingClientRect อ้าง viewport เสมอ */
                function centerDetailModal() {
                    if (!detailOverlay || !detailOverlay.classList.contains('show')) { return; }
                    var box = detailOverlay.querySelector('.sd2-dt-box');
                    if (!box) { return; }
                    box.style.transform = 'none';
                    var r = box.getBoundingClientRect();
                    if (!r.width) { return; }
                    var dx = Math.round((window.innerWidth - r.width) / 2 - r.left);
                    var dy = Math.round((window.innerHeight - r.height) / 2 - r.top);
                    /* ★ 25/08: overlay ถูกย้ายไป <body> แล้ว flex จึงจัดกลางให้ถูกอยู่แล้ว ปกติ dx/dy = 0
                       ถ้ายังตั้ง translate() ทิ้งไว้ทุกครั้ง ค่าเก่าจะค้างไปถึงการเปิดครั้งถัดไป
                       (กล่องใบใหม่โผล่มาเยื้อง แล้วค่อยเด้งกลับกลางจอ = กระตุก) จึงตั้งเฉพาะตอนที่ต้องแก้จริง */
                    if (Math.abs(dx) <= 1 && Math.abs(dy) <= 1) { box.style.transform = ''; return; }
                    box.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
                }
                function recenterDetailSoon() {
                    if (window.requestAnimationFrame) { requestAnimationFrame(centerDetailModal); } else { tmo(centerDetailModal, 0); }
                }
                /* โครงร่างระหว่างรอข้อมูล — โครงเดียวกับที่ renderDetail() วาดจริง (grid 12 ช่อง + section + แถวรายการ)
                   เพื่อให้ความสูงกล่องใกล้เคียงของจริงตั้งแต่เฟรมแรก ข้อมูลมาถึงแล้วกล่องแทบไม่ขยับ */
                function detailSkeletonHtml() {
                    var cells = '';
                    for (var i = 0; i < 12; i++) {
                        cells += '<div class="sd2-dt-cell"><div class="bar k"></div><div class="bar v"></div></div>';
                    }
                    var rows = '';
                    for (var j = 0; j < 3; j++) {
                        rows += '<div class="sd2-dt-pay"><span class="bar" style="width:150px;"></span><span class="bar" style="width:80px;"></span></div>';
                    }
                    return ('<div class="sd2-dt-skel" aria-busy="true" aria-label="' + env.t("label.lead.loading") + '">')
                        + '<div class="sd2-dt-grid">' + cells + '</div>'
                        + '<div class="bar sec"></div>' + rows
                        + '<div class="bar sec"></div>' + rows
                        + '</div>';
                }
                function openDetail(id) {
                    detailBody.innerHTML = detailSkeletonHtml();
                    // ย้าย overlay ไป <body> — หลุดจาก .layout-main ที่มี transform (containing block ของ position:fixed)
                    if (detailOverlay.parentNode !== document.body) { document.body.appendChild(detailOverlay); }
                    // บังคับตำแหน่งด้วย inline style ให้เต็มจอ + กลางจอแน่นอน (override CSS/ancestor)
                    detailOverlay.style.position = 'fixed'; detailOverlay.style.top = '0'; detailOverlay.style.left = '0';
                    detailOverlay.style.width = '100vw'; detailOverlay.style.height = '100vh';
                    detailOverlay.style.display = 'flex'; detailOverlay.style.alignItems = 'center'; detailOverlay.style.justifyContent = 'center';
                    detailOverlay.style.zIndex = '99999'; detailOverlay.style.padding = '20px'; detailOverlay.style.boxSizing = 'border-box';
                    detailOverlay.style.background = 'rgba(20,23,40,.45)';
                    detailOverlay.classList.add('show');
                    recenterDetailSoon();
                    env.fetch('/rvapi?action=detail&id=' + encodeURIComponent(id))
                        .then(function (r) { return r.json(); })
                        .then(function (d) { renderDetail((d && d.result) || null); recenterDetailSoon(); })
                        .catch(function (err) { detailBody.innerHTML = ('<div class="sd2-dt-empty">' + env.t("label.rv.detail_load_fail") + ' ') + esc(String(err)) + '</div>'; recenterDetailSoon(); });
                }
                function closeDetail() {
                    detailOverlay.classList.remove('show');
                    detailOverlay.style.display = 'none';
                    /* ★ 25/08: ล้างสถานะที่ค้างจากใบก่อนหน้า ไม่ให้ไปโผล่ตอนเปิดใบถัดไป
                       - transform: ค่าที่คำนวณไว้กับขนาดกล่องใบเก่า
                       - scrollTop: ถ้าเลื่อนดูใบยาว ๆ ค้างไว้ ใบใหม่จะเปิดมากลางเนื้อหา */
                    var box = detailOverlay.querySelector('.sd2-dt-box');
                    if (box) { box.style.transform = ''; box.scrollTop = 0; }
                }
                document.getElementById('sd2DetailClose').addEventListener('click', closeDetail);
                // ปุ่มเปิดฟอร์มใบเสร็จจริง RV-01 จาก modal รายละเอียด (รายการสินค้าเต็มอยู่บนฟอร์ม)
                var dtOpenForm = document.getElementById('sd2DtOpenForm');
                if (dtOpenForm) {
                    dtOpenForm.addEventListener('click', function (e) {
                        e.stopPropagation();
                        /* ★ ฟอร์มต้องใช้เลขที่ฝั่ง ERP เท่านั้น — 11/09 เลิก fallback ไป sd2DtTxno (เลขของ CRM)
                           เพราะส่งไปแล้วได้หน้าเปล่าเงียบ ๆ (ดูเหตุผลเต็มที่ openReceiptPreview) ไม่มีก็บอกผู้ใช้ไปตรง ๆ */
                        var formTxno = sd2DtPrintTxno || '';
                        if (formTxno) {
                            env.open('/rvreport?txno=' + encodeURIComponent(formTxno), '_blank');
                        } else {
                            toast(env.t("label.rv.not_synced_erp"));
                        }
                    });
                }
                detailOverlay.addEventListener('click', function (e) { if (e.target === detailOverlay) { closeDetail(); } });
                listen(window, 'resize', centerDetailModal);

                // ---------- คลิกในเอกสาร: รายงาน / แว่นขยาย / ดาวน์โหลด / ปิด popover ----------
                listen(document, 'click', function (e) {
                    var t = e.target;
                    var rep = t.closest && t.closest('.sd2-report');
                    if (rep) {
                        e.stopPropagation();
                        var repRow = rep.closest('tr');
                        pendingReportId = repRow ? repRow.getAttribute('data-id') : '';
                        var docNameEl = document.getElementById('sd2PopDocName');
                        var docNoCell = repRow && repRow.cells[1];
                        var shownTxno = docNoCell ? docNoCell.textContent.trim() : '';
                        /* ★ ปุ่มพิมพ์ฟอร์มต้องใช้เลขที่ฝั่ง ERP (data-print-txno) ไม่ใช่เลขที่ที่โชว์ในตาราง
                           ★ 11/09: เลิก fallback ไปใช้ shownTxno (เลขของ CRM) — Jasper อ่านคนละฐาน หาไม่เจอแล้วคืน
                           หน้าเปล่าแบบ 200 OK เงียบ ๆ ไม่มีค่าก็ปล่อยว่างไว้ ให้ openReceiptPreview() แจ้งเหตุผลแทน */
                        pendingReportTxno = (repRow && repRow.getAttribute('data-print-txno')) || '';
                        if (docNameEl) {
                            docNameEl.textContent = shownTxno || '—';   // โชว์เลขที่ของ CRM ตามที่ผู้ใช้เห็นในตาราง
                        }
                        openPopAt(pop, rep, 300);
                        return;
                    }

                    var eyeBtn = t.closest && t.closest('.sd2-eye-btn');
                    if (eyeBtn) {
                        e.stopPropagation();
                        var eyeRow = eyeBtn.closest('tr');
                        var rvId = eyeRow ? eyeRow.getAttribute('data-id') : '';
                        /* เลขที่ฝั่ง ERP มีเฉพาะใน list (print_forms) — detail API ไม่คืนมา จึงต้องจำจากแถวที่กด */
                        sd2DtPrintTxno = (eyeRow && eyeRow.getAttribute('data-print-txno')) || '';
                        if (rvId) { openDetail(rvId); } else { toast(env.t("label.rv.no_id_detail")); }
                        return;
                    }

                    // ★ กดแถวเอกสาร → เปิดรายละเอียดใบนั้น (เดิมพาไปหน้า "สร้างใหม่" เปล่า ๆ ทำให้เข้าใจว่าไม่มีเนื้อหา)
                    var tr = t.closest && t.closest('tr[data-st]');
                    if (tr && !t.closest('.sd2-approve-btn') && !t.closest('.sd2-eye-btn') && !t.closest('.sd2-dl') && !t.closest('.sd2-report')) {
                        var rowId = tr.getAttribute('data-id');
                        sd2DtPrintTxno = tr.getAttribute('data-print-txno') || '';
                        if (rowId) { openDetail(rowId); }
                        else { env.navigate("/sales/receipts/new"); }
                        return;
                    }

                    var mag = t.closest && t.closest('.sd2-mag');
                    if (mag) { e.stopPropagation(); openPopAt(itemsPop, mag, 240); return; }

                    var rowlink = t.closest && t.closest('.sd2-rowlink');
                    if (rowlink) { env.navigate("/sales/receipts/new"); return; }

                    var dlb = t.closest && t.closest('.sd2-dl');
                    if (dlb) {
                        e.stopPropagation();
                        // ★ PDF → เปิดหน้าพรีวิว HTML (มีปุ่มพิมพ์/บันทึกเป็น PDF); รูปภาพ → วาดลง canvas เปิดเป็นไฟล์รูปภาพล้วน ๆ
                        openReceiptPreview(pendingReportId, dlb.getAttribute('data-type'));
                        return;
                    }

                    if (!(t.closest && (t.closest('.sd2-pop') || t.closest('.sd2-menu') || t.closest('.sd2-product') || t.closest('#sd2FilterBtn')))) {
                        closeAll();
                    }
                });
                listen(window, 'resize', closeAll);
                /* ★ 25/08: capture=true ทำให้ handler นี้ยิงตอนเลื่อนใน .sd2-dt-box (max-height 88vh + overflow auto) ด้วย
                   = เรียก closeAll() รัวทุกเฟรมที่เลื่อนอ่านรายละเอียด ทั้งที่ตอน modal เปิดอยู่ไม่มี popover ให้ปิดเลย */
                listen(window, 'scroll', function () {
                    if (detailOverlay.classList.contains('show')) { return; }
                    closeAll();
                }, true);

  /* the entry points of the inline handlers and of the window.* functions */
  
  var EXPORTED = [];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    // the two boxes the script moved to <body> (out of the transformed .layout-main) go with the screen
    [overlay, detailOverlay].forEach(function (el) { if (el && el.parentNode === document.body) { document.body.removeChild(el); } });
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
  };
}
